insert into dr(k,v) values ('t.start', clock_timestamp()::text);
insert into dr(k,v) select 'pre.events_md5', md5(string_agg(row(id,title,description,category,venue,locality,lat,lng,starts_at,ends_at,status,is_hidden,organiser_user_id,organiser_business_id,organiser_hub_id,is_platform_event,has_tickets,tickets_sold,cover_url,ticket_url,hub_visibility,calendar_approved)::text,'|' order by id)) from public.events;
insert into dr(k,v) select 'pre.ticketing_md5', md5(coalesce((select string_agg(t::text,'|' order by t.id) from public.event_ticket_types t),'')||coalesce((select string_agg(o::text,'|' order by o.id) from public.event_ticket_orders o),'')||coalesce((select string_agg(k::text,'|' order by k.id) from public.event_tickets k),''));
insert into dr(k,v) select 'pre.activities_md5', md5(coalesce((select string_agg(a::text,'|' order by a.id) from public.regular_activities a),'')||coalesce((select string_agg(r::text,'|' order by r.id) from public.activity_schedule_rules r),'')||coalesce((select string_agg(x::text,'|' order by x.id) from public.activity_exceptions x),''));
insert into dr(k,v) select 'pre.events_policies_md5', (select md5(string_agg(policyname||'|'||cmd||'|'||roles::text||'|'||coalesce(qual,'')||'|'||coalesce(with_check,''),'#' order by policyname)) from pg_policies where schemaname='public' and tablename='events');
insert into dr(k,v) select 'pre.reserve_acl', coalesce(proacl::text,'') from pg_proc where oid='public.reserve_ticket_basket(uuid,uuid,jsonb,integer,integer,jsonb,text)'::regprocedure;
insert into dr(k,v) select 'pre.notification_log', count(*)::text from public.notification_log;
  insert into dr(k,v) values ('pre.anon_events', coalesce(r,'(null)'));
  insert into dr(k,v) values ('pre.activity_sessions', coalesce(r,'(null)'));
insert into dr(k,v) select 'post.events_md5_same', ((select md5(string_agg(row(id,title,description,category,venue,locality,lat,lng,starts_at,ends_at,status,is_hidden,organiser_user_id,organiser_business_id,organiser_hub_id,is_platform_event,has_tickets,tickets_sold,cover_url,ticket_url,hub_visibility,calendar_approved)::text,'|' order by id)) from public.events) = (select v from dr where k='pre.events_md5'))::text;
insert into dr(k,v) select 'post.ticketing_md5_same', ((select md5(coalesce((select string_agg(t::text,'|' order by t.id) from public.event_ticket_types t),'')||coalesce((select string_agg(o::text,'|' order by o.id) from public.event_ticket_orders o),'')||coalesce((select string_agg(k::text,'|' order by k.id) from public.event_tickets k),''))) = (select v from dr where k='pre.ticketing_md5'))::text;
insert into dr(k,v) select 'post.activities_md5_same', ((select md5(coalesce((select string_agg(a::text,'|' order by a.id) from public.regular_activities a),'')||coalesce((select string_agg(r::text,'|' order by r.id) from public.activity_schedule_rules r),'')||coalesce((select string_agg(x::text,'|' order by x.id) from public.activity_exceptions x),''))) = (select v from dr where k='pre.activities_md5'))::text;
insert into dr(k,v) select 'post.events_original_policies_same', ((select md5(string_agg(policyname||'|'||cmd||'|'||roles::text||'|'||coalesce(qual,'')||'|'||coalesce(with_check,''),'#' order by policyname)) from pg_policies where schemaname='public' and tablename='events' and policyname not in ('events_contributor_read','events_cancelled_public_read')) = (select v from dr where k='pre.events_policies_md5'))::text;
insert into dr(k,v) select 'post.events_policy_names', string_agg(policyname,',' order by policyname) from pg_policies where schemaname='public' and tablename='events';
insert into dr(k,v) select 'post.reserve_acl_same', (coalesce(proacl::text,'') = (select v from dr where k='pre.reserve_acl'))::text from pg_proc where oid='public.reserve_ticket_basket(uuid,uuid,jsonb,integer,integer,jsonb,text)'::regprocedure;
insert into dr(k,v) select 'post.reserve_shape', prosecdef::text||'|'||coalesce(proconfig::text,'')||'|'||pg_get_function_result(oid) from pg_proc where oid='public.reserve_ticket_basket(uuid,uuid,jsonb,integer,integer,jsonb,text)'::regprocedure;
insert into dr(k,v) select 'post.reserve_has_multi_perf_and_key_share', (prosrc ilike '%MULTI_PERFORMANCE%' and prosrc ilike '%for key share%')::text from pg_proc where oid='public.reserve_ticket_basket(uuid,uuid,jsonb,integer,integer,jsonb,text)'::regprocedure;
insert into dr(k,v) select 'post.new_tables', string_agg(relname,',' order by relname) from pg_class c where c.relnamespace='public'::regnamespace and c.relkind='r' and relname in ('event_occurrences','event_submissions','event_change_requests','event_change_log','event_organiser_trust');
insert into dr(k,v) select 'post.events_new_cols', string_agg(attname,',' order by attname) from pg_attribute where attrelid='public.events'::regclass and attname in ('is_dated_run','organiser_name','source','submission_id') and not attisdropped;
insert into dr(k,v) select 'post.events_flags', (count(*) filter (where is_dated_run) )::text||'|'||(count(*) filter (where source is not null))::text||'|'||(count(*) filter (where organiser_name is not null))::text||'|'||count(*)::text from public.events;
insert into dr(k,v) select 'post.new_functions_anon_executable', coalesce(string_agg(p.oid::regprocedure::text,','),'none') from pg_proc p where p.pronamespace='public'::regnamespace and p.oid not in (select oid from pre_fn) and has_function_privilege('anon',p.oid,'execute');
insert into dr(k,v) select 'post.new_functions_authenticated_executable', coalesce(string_agg(p.proname,',' order by p.proname),'none') from pg_proc p where p.pronamespace='public'::regnamespace and p.oid not in (select oid from pre_fn) and has_function_privilege('authenticated',p.oid,'execute');
insert into dr(k,v) select 'post.new_tables_anon_privileges', coalesce(string_agg(table_name||':'||privilege_type,','),'none') from information_schema.table_privileges where grantee='anon' and table_schema='public' and table_name in ('event_occurrences','event_submissions','event_change_requests','event_change_log','event_organiser_trust');
insert into dr(k,v) select 'post.new_tables_rls', string_agg(relname||':'||relrowsecurity::text,',' order by relname) from pg_class where relnamespace='public'::regnamespace and relname in ('event_occurrences','event_submissions','event_change_requests','event_change_log','event_organiser_trust');
insert into dr(k,v) select 'post.fetch_operations', coalesce((select value from public.admin_config where key='fetch.operations'),'(absent)');
  insert into dr(k,v) values ('post.anon_events', coalesce(r,'(null)'));
insert into dr(k,v) values ('t.after_structural', clock_timestamp()::text);
